INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "马殷", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁封马殷为楚王”中为受封者。", "biography": null, "status": "draft", "id": "7115610f-10b4-5211-b4a5-d2d089e6db83"}, {"name": "高郁", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁三年条所见人物：高郁。", "biography": null, "status": "draft", "id": "5c9c4658-2c67-5ef1-bcde-997099768500"}, {"name": "马希范", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平三年条所见人物：马希范。", "biography": null, "status": "draft", "id": "6c13c07c-57cf-596e-9247-ba0556ac4737"}, {"name": "李存勖", "aliases": ["李存勗", "李亚子", "后唐庄宗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "908年继承晋王之位，923年在魏州称帝，国号唐；同年率军灭后梁。", "biography": "908年继承晋王之位，923年在魏州称帝，国号唐；同年率军灭后梁。", "status": "draft", "id": "4e068da9-c8dd-5a31-a747-87669e3bf993"}, {"name": "高季昌", "aliases": ["高季兴"], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“高季昌受命为荆南节度使”中为受任者。", "biography": null, "status": "draft", "id": "e1d9e2c4-6e41-5d7c-8d65-eb79a2407418"}, {"name": "马希声", "aliases": ["馬希聲"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：马希声，武安节度副使判长沙府、获委知政总军者。", "biography": null, "status": "draft", "id": "5dca3ac0-5512-58ab-a330-ff34cb75ede8"}, {"name": "杨昭遂", "aliases": ["楊昭遂"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：杨昭遂，希声妻族、谋代高郁者。", "biography": null, "status": "draft", "id": "8c46f7c2-59ca-51b9-bddf-237d30a810ee"}, {"name": "李嗣源", "aliases": ["李亶", "后唐明宗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李存勖麾下的重要将领。参与908年潞州解围，923年袭取郓州并率前军进入大梁。", "biography": "李存勖麾下的重要将领。参与908年潞州解围，923年袭取郓州并率前军进入大梁。", "status": "draft", "id": "5d1886ff-b3ec-56f6-a154-b5633c294037"}, {"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "聂夷中", "aliases": ["聶夷中"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：聂夷中，被引诗的作者。", "biography": null, "status": "draft", "id": "ea541bcf-9d28-546b-90cd-aebdf7acc580"}, {"name": "董璋", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：董璋。", "biography": null, "status": "draft", "id": "ecbba4d7-b26a-5c43-ad24-180221fafb2b"}, {"name": "孟容", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：孟容，西川右都押牙，被论死资州税官的兄长。", "biography": null, "status": "draft", "id": "3b016787-e4b7-5d5e-8b85-fb4e0afc4786"}, {"name": "冯璩", "aliases": ["馮璩"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：冯璩，为税官请免的观察判官。", "biography": null, "status": "draft", "id": "0ffb636b-eebc-59cb-9137-6f8b164a0898"}, {"name": "王处回", "aliases": ["王處回"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王处回，为税官请免的中门副使。", "biography": null, "status": "draft", "id": "159fd2b3-759b-522a-a971-11356c6fe970"}, {"name": "孟知祥", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：孟知祥。", "biography": null, "status": "draft", "id": "07a6bbea-9699-5f43-aef3-481401e2ed5e"}, {"name": "钱镠", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“钱氏军队攻取温州，卢佶被杀”中为发令者。", "biography": null, "status": "draft", "id": "d61d1f96-7af5-5367-8be8-7a25ee7c85ae"}, {"name": "安重诲", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷269贞明二年条所见人物：安重诲。", "biography": null, "status": "draft", "id": "ce1aed16-1e3c-550a-954b-f37ff4743d0c"}, {"name": "乌昭遇", "aliases": ["烏昭遇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：乌昭遇，吴越使者。", "biography": null, "status": "draft", "id": "ca900d22-fffa-5bb1-8796-4d192bc3a5de"}, {"name": "韩玫", "aliases": ["韓玫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：韩玫，吴越使者。", "biography": null, "status": "draft", "id": "447619f2-bda7-5ad0-a033-0919c7e23d2f"}, {"name": "钱传瓘", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“钱氏军队攻取温州，卢佶被杀”中为出征者。", "biography": null, "status": "draft", "id": "6674e6a1-d66d-5e57-af1f-2d98f55021a1"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
